import{_ as e,o as s,c as r,ag as a}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Part 16 — TLS / SSL","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_16_TLS.md","filePath":"todo/study_plan/parts/Part_16_TLS.md"}'),n={name:"todo/study_plan/parts/Part_16_TLS.md"};function i(o,t,d,l,c,h){return s(),r("div",null,[...t[0]||(t[0]=[a(`<h1 id="part-16-—-tls-ssl" tabindex="-1">Part 16 — TLS / SSL <a class="header-anchor" href="#part-16-—-tls-ssl" aria-label="Permalink to &quot;Part 16 — TLS / SSL&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Week 8 (shared). <strong>Budget: ~3-4 hrs.</strong></p></blockquote><h2 id="_16-tls-ssl-—-topic-inventory" tabindex="-1">16 TLS / SSL — topic inventory <a class="header-anchor" href="#_16-tls-ssl-—-topic-inventory" aria-label="Permalink to &quot;16 TLS / SSL — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>TLS 1.2 vs TLS 1.3 — handshake differences (1-RTT, 0-RTT)</td><td>🔴 💼 🔐 🎯</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: capture a TLS 1.2 handshake and a TLS 1.3 handshake with tcpdump or Wireshark; count RTTs to first byte (30 min)</td></tr><tr><td>2</td><td>Full handshake walkthrough — ClientHello, ServerHello, key exchange</td><td>🔴 💼 🔐 🎯</td><td>D</td><td>2 hrs 30 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: <code>openssl s_client -connect google.com:443 -tls1_3 -trace</code> — identify ClientHello, ServerHello, key exchange in the trace output (30 min)</td></tr><tr><td>3</td><td>Cipher suites — naming convention, what each component does</td><td>🔴 💼 🔐 🎯</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: run <code>nmap --script ssl-enum-ciphers -p 443 yourdomain.com</code> against your service; identify which suites are weak and how to disable them in Spring Boot (30 min)</td></tr><tr><td>4</td><td>Perfect Forward Secrecy — why DHE / ECDHE matters</td><td>🔴 💼 🔐 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>5</td><td>SNI — Server Name Indication, ESNI / ECH</td><td>🔴 💼 🔐 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>6</td><td>ALPN — protocol selection (HTTP/2 negotiation)</td><td>🟠 💼 🔐</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>7</td><td>Session resumption — session IDs, session tickets</td><td>🟠 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>8</td><td>OCSP stapling</td><td>🟠 💼 🔐</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>9</td><td>HSTS, preload lists</td><td>🟠 💼 🔐</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>10</td><td>Mutual TLS (mTLS) — when, how, cert rotation</td><td>🟠 💼 🔐</td><td>D</td><td>3 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>(Cross-ref Part 17 PKI) · 💻 Warm-up: configure Spring Boot with server.ssl.client-auth=need; generate client cert with openssl; curl with --cert/--key; observe rejection without cert (30 min)</td></tr><tr><td>11</td><td>Common attacks — BEAST, CRIME, POODLE, Heartbleed, downgrade attacks</td><td>🟠 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>12</td><td>TLS terminator placement (LB, sidecar, app)</td><td>🟠 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>13</td><td>SSL Labs grading criteria</td><td>🟡 🔐</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>14</td><td>Wireshark TLS inspection</td><td>🟢 🔐</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~10.5 hrs</td><td>~0.95 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~20.75 hrs</td><td>~1.9 wk</td><td></td></tr><tr><td>Full Part (all items including 🟡 + 🟢)</td><td>~22.25 hrs</td><td>~2 wk</td><td></td></tr></tbody></table><h2 id="key-diagrams" tabindex="-1">Key diagrams <a class="header-anchor" href="#key-diagrams" aria-label="Permalink to &quot;Key diagrams&quot;">​</a></h2><p><strong>TLS 1.3 handshake (1-RTT):</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sequenceDiagram</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant C as Client</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    participant S as Server</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C,S: 1-RTT handshake (1 round-trip before encrypted data)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;S: ClientHello&lt;br/&gt;(supported ciphers, supported groups, key share for ECDHE, SNI)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S-&gt;&gt;C: ServerHello + EncryptedExtensions&lt;br/&gt;(chosen cipher, key share, certificate, Finished)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C,S: Both sides now derive session keys via ECDHE</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;S: ChangeCipherSpec + Finished&lt;br/&gt;(over encrypted channel)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    S-&gt;&gt;C: Application data (encrypted)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C-&gt;&gt;S: Application data (encrypted)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Note over C,S: Optional 0-RTT for resumed sessions:&lt;br/&gt;client sends app data with ClientHello using prior session key</span></span></code></pre></div><blockquote><p>TLS 1.2 needed 2 round-trips. TLS 1.3 collapses to 1 (or 0 for resumed sessions). The savings matter for high-latency mobile networks and KYC SDK ↔ backend handshakes over poor connections.</p></blockquote><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> Walk through a TLS 1.3 full handshake. How is it different from TLS 1.2? <ul><li><strong>Why asked:</strong> Senior canonical. TLS 1.3: 1-RTT — ClientHello includes key share guess (ECDHE), ServerHello includes server&#39;s key share + chosen cipher + cert + Finished. App data starts after 1 round trip. TLS 1.2: 2-RTT — ClientHello/ServerHello establish ciphers, then key exchange messages, then ChangeCipherSpec, then Finished. TLS 1.3 also removed RSA key exchange, MD5, SHA-1, weak ciphers — much smaller attack surface.</li></ul></li><li><strong>Q:</strong> What is Perfect Forward Secrecy, why does it matter, and how does ECDHE achieve it? <ul><li><strong>Why asked:</strong> Senior crypto-knowledge. PFS: even if server&#39;s long-term private key is compromised later, past session keys remain safe. With RSA key exchange (old), compromised server key lets attacker decrypt all past captured sessions. ECDHE: ephemeral keys per session — server&#39;s long-term key only authenticates, doesn&#39;t encrypt. Past sessions stay private.</li></ul></li><li><strong>Q:</strong> SNI — what problem does it solve, and what&#39;s the privacy issue? <ul><li><strong>Why asked:</strong> Modern TLS. SNI: client tells server which hostname it wants (in plaintext ClientHello) — needed for shared-IP hosting (one IP, many TLS certs). Privacy issue: SNI leaks the destination hostname even over TLS. ESNI / ECH (Encrypted Client Hello) encrypts SNI using a DNS-published public key — fixes the leak but deploys slowly.</li></ul></li><li><strong>Q:</strong> Cipher suite <code>TLS_AES_256_GCM_SHA384</code> — what does each component mean? <ul><li><strong>Why asked:</strong> Tests fluency. TLS_ = TLS-specific. AES_256_GCM = symmetric encryption (AES, 256-bit, GCM mode for AEAD). SHA384 = hash for key derivation + Finished message HMAC. TLS 1.3 simplified naming: no more key exchange + signature algorithm in the name (those are negotiated separately via key shares + signature_algorithms extension).</li></ul></li><li><strong>Q:</strong> Your KYC platform&#39;s mTLS to a regulated bank fails after their cert rotation. Walk through your debug. <ul><li><strong>Why asked:</strong> Operational depth. (1) <code>openssl s_client -connect bank:443 -showcerts</code> to see what the bank presents. (2) Verify your truststore has the bank&#39;s new CA. (3) Check your client cert is current + signed by a CA the bank trusts. (4) Check SAN matches the hostname. (5) Check OCSP / CRL — if revocation lookup fails, some clients reject. Your error message should narrow it: SSLHandshakeException variants.</li></ul></li><li><strong>Q:</strong> Session resumption — session IDs vs session tickets. <ul><li><strong>Why asked:</strong> Performance + scaling. Session IDs: server stores session state, indexed by ID. Works for single-server. Doesn&#39;t scale across load-balanced fleets without sticky sessions. Session tickets: server gives client an encrypted &quot;ticket&quot; containing the session state. Stateless on server. Scales horizontally. TLS 1.3 simplified to PSK (Pre-Shared Key) for resumption.</li></ul></li><li><strong>Q:</strong> What does OCSP stapling solve? <ul><li><strong>Why asked:</strong> TLS performance + privacy. Without stapling: client queries OCSP responder during handshake to check cert revocation status. Adds latency, leaks visit to CA, fails-closed when responder is down. With stapling: server pre-fetches OCSP response, attaches to handshake. No extra client RTT, no leak to CA, more robust.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> Your TLS connection negotiates TLS 1.0 even though you have TLS 1.3 configured. Why? <ul><li><strong>Gotcha:</strong> Likely a client doesn&#39;t support TLS 1.3 OR a downgrade attack (modern TLS has downgrade protection via the random in ClientHello). Other causes: TLS terminator (LB) configuration, intermediate proxy. Diagnose: <code>openssl s_client -tls1_3 -connect host:443</code> and check protocol used.</li></ul></li><li><strong>Q:</strong> Your client successfully connects to <code>kyc-bank.com</code> but fails to <code>staging.kyc-bank.com</code>. Both have valid certs. What&#39;s wrong? <ul><li><strong>Gotcha:</strong> SNI. Without SNI, server returns default cert. If staging is on shared IP, default cert is for kyc-bank.com → cert mismatch on staging request. Fix: client must send SNI = staging.kyc-bank.com. Most modern clients do this automatically; ancient clients (Java 7) don&#39;t.</li></ul></li><li><strong>Q:</strong> You enabled HSTS with <code>max-age=31536000</code>. After a routine cert mistake (wrong cert deployed), users complain they can&#39;t bypass the cert error. Why? <ul><li><strong>Gotcha:</strong> HSTS = strict transport security. Browsers cache the HSTS policy and refuse plaintext HTTP and refuse to bypass cert errors for the duration of <code>max-age</code>. Mistake-rollback requires fixing the cert (or rotating to a known-good one) — users can&#39;t bypass. Set <code>max-age=600</code> initially to test, then ramp.</li></ul></li><li><strong>Q:</strong> Your security team scans found &quot;weak cipher&quot; warning for <code>TLS_RSA_WITH_AES_256_GCM_SHA384</code>. But AES-256-GCM is strong. What&#39;s the issue? <ul><li><strong>Gotcha:</strong> <code>TLS_RSA_WITH_*</code> uses RSA key exchange (not ECDHE). No Perfect Forward Secrecy — past sessions vulnerable if server&#39;s long-term key is compromised. Fix: disable RSA key exchange cipher suites; use only <code>TLS_ECDHE_*</code> (or <code>TLS_AES_*</code> in TLS 1.3, which is implicit ECDHE).</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>End-to-end TLS handshake walk-through</strong> (~3 hrs rows 1 + 2 combined) — Mastery item across Parts 16 + 17. Capture with Wireshark or openssl s_client trace. Identify each handshake message. Interview-canonical.</li><li><strong>mTLS rotation for KYC bank integration</strong> (~3 hrs row 10) — directly your platform. Dual-cert overlap window, rotation procedure, monitoring, alerting. Becomes STAR-story material.</li><li><strong>Cipher suite policy + audit</strong> (~2.5 hrs rows 3 + 4 + 11) — define a modern cipher suite policy for your KYC platform. Test against current setup with SSL Labs. Address any non-PFS ciphers, weak hashes.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up TLS exercises are listed inline in the topic-table Resources column (counted in main Time summary). Longer exercises below are tracked separately.</p><h3 id="practice-—-mid-level-30-60-min-each" tabindex="-1">Practice — mid-level (~30-60 min each) <a class="header-anchor" href="#practice-—-mid-level-30-60-min-each" aria-label="Permalink to &quot;Practice — mid-level (~30-60 min each)&quot;">​</a></h3><ol><li><strong>TLS handshake inspection with openssl s_client</strong> (~45 min) — <code>openssl s_client -connect google.com:443 -tls1_3 -trace -msg</code>. Identify ClientHello, ServerHello, certificate, Finished. Repeat with <code>-tls1_2</code>. Compare round-trip count.</li><li><strong>Spring Boot HTTPS server with custom keystore</strong> (~60 min) — generate self-signed cert (cross-ref Part 17 warm-ups). Configure <code>server.ssl.*</code> in application.yml. Hit with curl <code>--cacert</code>. Test client without cacert (cert error).</li><li><strong>Cipher suite scanning</strong> (~30 min) — <code>nmap --script ssl-enum-ciphers -p 443 your-host</code>. Identify supported suites. Cross-check against a &quot;good&quot; recommendation (Mozilla TLS config generator). Note any weak / deprecated.</li></ol><h3 id="advanced-—-senior-grade-depth-60-min-each" tabindex="-1">Advanced — senior-grade depth (~60+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-60-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~60+ min each)&quot;">​</a></h3><ol start="4"><li><strong>End-to-end mTLS Spring Boot setup</strong> (~90 min) — server with <code>server.ssl.client-auth=need</code> + truststore. Java client using <code>SSLContext</code> + client cert from p12. Test happy path, client without cert, client with revoked cert. Document full setup.</li><li><strong>TLS terminator placement decision</strong> (~60 min) — given your KYC platform&#39;s architecture (SDK → CloudFront → ALB → app), document where TLS terminates at each hop, what protocol between hops, key/cert management. Where would you do TLS pass-through vs re-encryption?</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~2.25 hrs</td><td>~0.2 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~2.5 hrs</td><td>~0.23 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~4.75 hrs</strong></td><td><strong>~0.45 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~2 hrs for Part 16 across 4 in-table warm-ups (tcpdump TLS 1.2 vs 1.3 handshake capture, nmap cipher-suite scan + Spring Boot disablement, mTLS Spring Boot <code>client-auth=need</code> setup, plus the original <code>openssl s_client -trace</code> walkthrough).</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. TLS 1.3 vs 1.2 — round-trip difference?</strong> A. TLS 1.2: 2-RTT before encrypted app data. TLS 1.3: 1-RTT (or 0-RTT for resumed sessions). TLS 1.3 also dropped RSA key exchange, weak ciphers, MD5, SHA-1.</p><p><strong>Q. Perfect Forward Secrecy in one sentence.</strong> A. Compromising the server&#39;s long-term private key does NOT let an attacker decrypt past captured sessions, because session keys are derived from ephemeral (per-session) ECDHE keys.</p><p><strong>Q. SNI — what&#39;s it for, what&#39;s its privacy issue?</strong> A. Client tells server which hostname it wants (plaintext in ClientHello) — needed for shared-IP hosting. Privacy issue: hostname is leaked even over TLS. ESNI / ECH fixes by encrypting SNI.</p><p><strong>Q. mTLS in one sentence.</strong> A. Mutual TLS — both server AND client present + verify certificates during handshake. Used for service-to-service auth (no JWT/password) and regulated B2B integrations.</p><p><strong>Q. Cipher suite components (TLS 1.2 style)?</strong> A. <code>TLS_&lt;keyexchange&gt;_&lt;authentication&gt;_WITH_&lt;bulk_cipher&gt;_&lt;MAC&gt;</code>. E.g., <code>TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384</code>: ECDHE key exchange, RSA cert auth, AES-256-GCM bulk, SHA384 PRF. TLS 1.3 simplified to just bulk + MAC.</p><p><strong>Q. OCSP stapling — why use it?</strong> A. Server pre-fetches OCSP response from CA and attaches to TLS handshake. Avoids client-side OCSP lookup (latency, privacy leak to CA, failure when CA is down).</p>`,32)])])}const g=e(n,[["render",i]]);export{u as __pageData,g as default};
